function voiceMealValues(){const f=$('#voice-meal-form'),v=Object.fromEntries(new FormData(f));let r=state.recipes.find(r=>r.id===v.recipe);if(!r&&v.recipe==='__new__'){const cleanName=String(voiceDraft?.text||'').replace(/\b(toi nay|toi mai|trua nay|trua mai|sang nay|sang mai|bua sang|bua trua|bua toi|nau|mon|cho \d+\s*nguoi)\b/gi,'').trim()||tr('Món gia đình mới','New family dish');r={id:uid(),name:cleanName.slice(0,120),category:'main',protein:'mixed',time:25,servings:4,yield:4,purposes:['main','friday'],ingredients:[],missingIngredients:[],prep:'',steps:[tr('Nấu theo cách quen của gia đình.','Cook according to your family style.')],custom:true,origin:'family',favorite:false}}if(!r)throw Error(tr('Chọn món từ danh sách hoặc chọn Tạo nhanh món mới.','Choose a dish from the list or quick-create a new dish.'));if(!/^\d{4}-\d{2}-\d{2}$/.test(v.date))throw Error('Chọn ngày.');const week=ensureWeek(state,monday(v.date)),m=week.days[v.date][v.type];return{...v,r,m,servings:v.servings===''?null:+v.servings}}
