 if(form.id==='assignment-form'){state.mealAssignments??={};state.mealAssignments[selectedDate+'/'+attendanceType]={cook:v.cook,shopper:v.shopper};save(tr('Đã lưu phân công cho bữa đang xem.','Tasks saved for this meal.'))}
 if(form.id==='weather-form'){requireOnline(tr('Lấy thời tiết','Weather lookup'));const res=await fetch('/.netlify/functions/weather?city='+encodeURIComponent(v.city),{credentials:'same-origin',cache:'no-store'}),data=await res.json();if(!res.ok)throw Error(data.error||'Chưa lấy được thời tiết.');state.settings.weatherCity=v.city;state.settings.liveWeather={...data,date:sydneyDate(),fresh:true};state.settings.weatherMark={date:sydneyDate(),temp:data.temp,source:'live'};save();closeModal();render()}
