document.addEventListener('change',async event=>{const username=event.target.dataset.accountRole;if(username){try{await accountRequest('role',{username,role:event.target.value});await accountsModal()}catch(e){toast(e.message,true)}}if(event.target.id==='theme-mode-select'){try{localStorage.setItem('bep-theme-mode',event.target.value)}catch{}applyThemePreferences();toast(tr('Đã cập nhật chế độ sáng / tối.','Updated light / dark theme mode.'))}if(event.target.id==='festival-theme-select'){try{localStorage.setItem('bep-festival-theme',event.target.value)}catch{}applyThemePreferences();toast(tr('Đã áp dụng chủ đề lễ hội.','Applied festival theme.'))}if(event.target.closest('#voice-meal-form'))voiceNeeds()});
