async function refreshGreetingWeather(){const city=state.settings.weatherCity;if(!city||Date.now()-(state.settings.liveWeather?.fetchedAt||0)<1800000)return;try{const res=await fetch('/.netlify/functions/weather?city='+encodeURIComponent(city),{credentials:'same-origin',cache:'no-store'});if(!res.ok)return;const data=await res.json();state.settings.liveWeather={...data,date:sydneyDate(),fresh:true};state.settings.weatherMark={date:sydneyDate(),temp:data.temp,source:'live'};if(canEdit())save();render()}catch{}}
