const onlineShareText=shareText;shareText=async function(text){if(!navigator.onLine||globalThis.BEP_OFFLINE){modal(tr('Chia sẻ khi offline','Share while offline'),`<p>${tr('Có thể sao chép danh sách ngay. Gửi qua Messenger cần mạng; app không tự gửi.','You can copy your list now. Messenger needs internet; this app does not send it automatically.')}</p><textarea id="share-content" class="input" rows="10" readonly>${esc(text)}</textarea>`,`<button class="btn primary" data-action="copy-share">${tr('Sao chép','Copy')}</button>`);return}return onlineShareText(text)};
document.addEventListener('click',event=>{const link=event.target.closest('a[href^="https://"]');if(link&&(!navigator.onLine||globalThis.BEP_OFFLINE)){event.preventDefault();toast(tr('Mở website bên ngoài cần mạng. Dữ liệu trong app vẫn dùng được offline.','External websites need internet. App data is still available offline.'),true)}},true);

function offlineReadyText(){return offlineIsReady===true?tr('Offline đã sẵn sàng trên thiết bị này.','Offline is ready on this device.'):offlineIsReady===false?tr('Chưa tải đủ để mở offline. Giữ app mở khi có mạng rồi kiểm tra lại.','Offline setup is incomplete. Keep the app open online, then check again.'):tr('Đang kiểm tra bản tải offline…','Checking offline availability…')}
navigator.serviceWorker?.addEventListener('message',event=>{if(event.data?.type==='OFFLINE_READY'){offlineIsReady=event.data.ready;$$('.offline-readiness').forEach(el=>el.textContent=offlineReadyText())}});
function checkOfflineReady(){navigator.serviceWorker?.controller?.postMessage({type:'CHECK_OFFLINE_READY',householdId:accountSession?.household?.id||null});setTimeout(()=>{if(offlineIsReady===null){offlineIsReady=false;$$('.offline-readiness').forEach(el=>el.textContent=offlineReadyText())}},3000)}
navigator.serviceWorker?.addEventListener('controllerchange',()=>setTimeout(checkOfflineReady,1000));navigator.serviceWorker?.ready.then(()=>setTimeout(checkOfflineReady,1000));
cloudSettings=async function(){if(!navigator.onLine||globalThis.BEP_OFFLINE){modal(tr('Dữ liệu đang lưu trên máy','Your data is saved on this device'),`<p>${tr('Có thể tiếp tục sửa thực đơn, lịch, đi chợ và ghi chi tiêu. Đồng bộ với người nhà cần mạng; thay đổi được giữ để đối chiếu khi kết nối lại.','Keep editing meals, availability, shopping and spending. Family synchronization needs internet; changes are retained for review when reconnecting.')}</p><p class="offline-readiness">${offlineReadyText()}</p>`,`<button class="btn" data-action="export">${tr('Xuất sao lưu','Export backup')}</button><button class="btn primary" data-personal="retry-online">${tr('Thử kết nối','Retry connection')}</button>`,true);return}if(accountSession){modal(tr('Đồng bộ gia đình','Family sync'),`<p><b>${esc(accountSession.household?.name||'')}</b> · ${esc(accountSession.household?.role||'')}</p><p>${esc(cloudStatusText())}</p><p class="hint">${tr('Mỗi người dùng tài khoản riêng. Thay đổi đồng thời được đối chiếu trước khi lưu.','Everyone uses their own account. Concurrent changes are reviewed before saving.')}</p>`,`<button class="btn" data-personal="accounts">${tr('Tài khoản & gia đình','Account & family')}</button><button class="btn primary" data-feature="cloud-sync">${tr('Đồng bộ ngay','Sync now')}</button>`,true);return}return accountsModal()};

function updateConnectivityIcon(){const offline=!navigator.onLine||globalThis.BEP_OFFLINE;let status=$('#network-status');if(!status){status=document.createElement('span');status.id='network-status';status.className='network-status';status.setAttribute('role','status');status.setAttribute('aria-live','polite');$('.top-actions')?.insertBefore(status,$('.top-actions .notification'))}const value=offline?'offline':'online';if(status.dataset.connection!==value){status.dataset.connection=value;status.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path class="wifi-wave wave-a" d="M3 8a15 15 0 0 1 18 0"/><path class="wifi-wave wave-b" d="M6 12a10 10 0 0 1 12 0"/><path class="wifi-wave wave-c" d="M9 16a5 5 0 0 1 6 0"/><circle cx="12" cy="20" r="1" fill="currentColor" stroke="none"/>'+ (offline?'<path class="wifi-slash" d="M3 3l18 18"/>':'')+'</svg><span>'+ (offline?'Offline':'Online')+'</span>'}status.setAttribute('aria-label',offline?tr('Offline · lưu trên máy, chờ kết nối','Offline · saving on device, waiting for connection'):tr('Online · có kết nối mạng','Online · network connected'));status.title=offline?tr('Dữ liệu trên máy vẫn dùng được','Your device data is still available'):tr('Có thể đồng bộ khi dịch vụ sẵn sàng','Sync is available when the service is ready')}
updateConnectivityIcon();
